var LangPack=LangPack||{},LangPack={LangJSON:null,LangXml:null,init:function(successFn){LangPack.loadLangJSON((function(){successFn&&successFn()}))},loadLangJSON:function(successFn){var filePath="./js/LanguagePack/HATMLanguage.json",localLang="zh-tw";ProjectFn.Wait([function(next){Log.alert("取得設備本地語言"),navigator.globalization.getLocaleName((function(locale){localLang=locale.value.toLowerCase(),localStorage.setItem("Lang",localLang),Log.alert(localLang),next()}),(function(){localStorage.setItem("Lang",localLang),next()}))}],(function(){$.getJSON(filePath,(function(LangJSON){Log.alert("getJSON Success"),LangPack.LangJSON=LangJSON,LangPack.setLang(LangJSON,(function(){successFn&&successFn()}))}),(function(){FnCtrl.alert("語言包無法載入","System Message",null,"OK")}))}))},setLang:function(HATMLanguage,successFn){var localLang=localStorage.Lang;Lang=new HashMap;for(var i=0;i<HATMLanguage.length;i++){switch(localLang){case"zh-cn":Lang.set(HATMLanguage[i].LCode,HATMLanguage[i].CN);break;case"zh-tw":case"en-us":case"en":case"ja":default:Lang.set(HATMLanguage[i].LCode,HATMLanguage[i].TW)}i==HATMLanguage.length-1&&(localStorage.setItem("LangVersion",AppConfig.LangVersion),successFn&&successFn())}}};